export const getProjectsControllerGetLedgerEntriesUrl = (id: string,
    params?: ProjectsControllerGetLedgerEntriesParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : value.toString())
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/projects/${id}/ledger-entries?${stringifiedParams}` : `/projects/${id}/ledger-entries`
}

